   439  struct Charset {
   440    inline bool sanitize (hb_sanitize_context_t *c) const
   441    {
   442      TRACE_SANITIZE (this);
   443
   444      if (unlikely (!c->check_struct (this)))
   445        return_trace (false);
   446      if (format == 0)
   447        return_trace (u.format0.sanitize (c, c->get_num_glyphs ()));
   448      else if (format == 1)
   449        return_trace (u.format1.sanitize (c, c->get_num_glyphs ()));
   450      else if (likely (format == 2))
   451        return_trace (u.format2.sanitize (c, c->get_num_glyphs ()));
   452      else
   453        return_trace (false);
   454    }
   455
   456    /* serialize a fullset Charset */
   457    inline bool serialize (hb_serialize_context_t *c, const Charset &src, unsigned int num_glyphs)
   458    {
   459      TRACE_SERIALIZE (this);
   460      unsigned int size = src.get_size (num_glyphs);
   461      Charset *dest = c->allocate_size<Charset> (size);
   462      if (unlikely (dest == nullptr)) return_trace (false);
   463      memcpy (dest, &src, size);
   464      return_trace (true);
   465    }
   466
   467    /* serialize a subset Charset */
   468    inline bool serialize (hb_serialize_context_t *c,
   469                           uint8_t format,
   470                           unsigned int num_glyphs,
   471                           const hb_vector_t<code_pair>& sid_ranges)
   472    {
   473      TRACE_SERIALIZE (this);
   474      Charset *dest = c->extend_min (*this);
   475      if (unlikely (dest == nullptr)) return_trace (false);
   476      dest->format.set (format);
   477      if (format == 0)
   478      {
   479        Charset0 *fmt0 = c->allocate_size<Charset0> (Charset0::min_size + HBUINT16::static_size * (num_glyphs - 1));
   480      if (unlikely (fmt0 == nullptr)) return_trace (false);
   481        unsigned int glyph = 0;
   482        for (unsigned int i = 0; i < sid_ranges.len; i++)
   483        {
   484          hb_codepoint_t sid = sid_ranges[i].code;
   485          for (int left = (int)sid_ranges[i].glyph; left >= 0; left--)
   486            fmt0->sids[glyph++].set (sid++);
   487        }
   488      }
   489      else if (format == 1)
   490      {
   491        Charset1 *fmt1 = c->allocate_size<Charset1> (Charset1::min_size + Charset1_Range::static_size * sid_ranges.len);
   492        if (unlikely (fmt1 == nullptr)) return_trace (false);
   493        for (unsigned int i = 0; i < sid_ranges.len; i++)
   494        {
   495          if (unlikely (!(sid_ranges[i].glyph <= 0xFF)))
   496            return_trace (false);
   497          fmt1->ranges[i].first.set (sid_ranges[i].code);
   498          fmt1->ranges[i].nLeft.set (sid_ranges[i].glyph);
   499        }
   500      }
   501      else /* format 2 */
   502      {
   503        Charset2 *fmt2 = c->allocate_size<Charset2> (Charset2::min_size + Charset2_Range::static_size * sid_ranges.len);
   504        if (unlikely (fmt2 == nullptr)) return_trace (false);
   505        for (unsigned int i = 0; i < sid_ranges.len; i++)
   506        {
   507          if (unlikely (!(sid_ranges[i].glyph <= 0xFFFF)))
   508            return_trace (false);
   509          fmt2->ranges[i].first.set (sid_ranges[i].code);
   510          fmt2->ranges[i].nLeft.set (sid_ranges[i].glyph);
   511        }
   512      }
   513      return_trace (true);
   514    }
   515
   516    /* parallel to above: calculate the size of a subset Charset */
   517    static inline unsigned int calculate_serialized_size (
   518                          uint8_t format,
   519                          unsigned int count)
   520    {
   521      unsigned int  size = min_size;
   522      if (format == 0)
   523        size += Charset0::min_size + HBUINT16::static_size * (count - 1);
   524      else if (format == 1)
   525        size += Charset1::min_size + Charset1_Range::static_size * count;
   526      else
   527        size += Charset2::min_size + Charset2_Range::static_size * count;
   528
   529      return size;
   530    }
   531
   532    inline unsigned int get_size (unsigned int num_glyphs) const
   533    {
   534      unsigned int size = min_size;
   535      if (format == 0)
   536        size += u.format0.get_size (num_glyphs);
   537      else if (format == 1)
   538        size += u.format1.get_size (num_glyphs);
   539      else
   540        size += u.format2.get_size (num_glyphs);
   541      return size;
   542    }
   543
   544    inline hb_codepoint_t get_sid (hb_codepoint_t glyph) const
   545    {
   546      if (format == 0)
   547        return u.format0.get_sid (glyph);
   548      else if (format == 1)
   549        return u.format1.get_sid (glyph);
   550      else
   551        return u.format2.get_sid (glyph);
   552    }
   553
   554    inline hb_codepoint_t get_glyph (hb_codepoint_t sid, unsigned int num_glyphs) const
   555    {
   556      if (format == 0)
   557        return u.format0.get_glyph (sid, num_glyphs);
   558      else if (format == 1)
   559        return u.format1.get_glyph (sid, num_glyphs);
   560      else
   561        return u.format2.get_glyph (sid, num_glyphs);
   562    }
   563
   564    HBUINT8       format;
   565    union {
   566      Charset0    format0;
   567      Charset1    format1;
   568      Charset2    format2;
   569    } u;
   570
   571    DEFINE_SIZE_MIN (1);
   572  };
